// Quadtree world streamer. The archipelago is covered by 1024 m root tiles that
// split toward the camera down to 64 m leaves; every node is the same 32×32
// grid, so detail falls off geometrically with distance. Nodes are generated by
// a small pool of workers and swapped in only when all four children are ready,
// so there are never holes and never a loading screen.
import * as THREE from 'three';
import type { ChunkRequest, ChunkResult, AtlasRequest, AtlasResult } from './chunk.worker';
import { makeInkMaterial } from '../render/inkMaterial';
import { makeGrassMesh } from './grass';
import { CollisionWorld } from './colliders';
import { WORLD_HALF } from './terrain';
import { Flora } from './flora';
import { smoothstep } from '../core/math';

const ROOT = 1024;
const MIN = 64;
const SPLIT_K = 1.5;

interface Prop {
  kind: number;
  x: number;
  y: number;
  z: number;
  r: number;
  h: number;
}

class QNode {
  children: QNode[] | null = null;
  state: 'empty' | 'loading' | 'ready' = 'empty';
  group: THREE.Group | null = null;
  grass: THREE.Mesh | null = null;
  flora: THREE.Mesh | null = null;
  props: Prop[] | null = null;
  lastUsed = 0;
  shown = false;
  split = false;
  constructor(readonly id: number, readonly x: number, readonly z: number, readonly size: number) {}
  dist(px: number, pz: number) {
    const dx = Math.max(this.x - px, 0, px - (this.x + this.size));
    const dz = Math.max(this.z - pz, 0, pz - (this.z + this.size));
    return Math.sqrt(dx * dx + dz * dz);
  }
}

export interface Atlas {
  res: number;
  half: number;
  height: Float32Array;
  biome: Uint8Array;
}

export class ChunkManager {
  readonly group = new THREE.Group();
  readonly terrainMat = makeInkMaterial({ outline: 1, shadeInk: 0.06 });
  readonly floraMat = makeInkMaterial({ wind: true, edgeId: 0.35, shadeInk: 0.2, outline: 1 });
  atlas: Atlas | null = null;
  onAtlas: ((a: Atlas) => void) | null = null;
  /** nodes currently drawn / waiting, for the debug readout */
  stats = { shown: 0, loading: 0, nodes: 0, tris: 0 };

  private roots: QNode[] = [];
  private nodes = new Map<number, QNode>();
  private nextId = 1;
  private workers: Worker[] = [];
  private load: number[] = [];
  private queue: QNode[] = [];
  private frame = 0;
  private cam = new THREE.Vector3();
  private leaves64: QNode[] = [];

  constructor(private collision: CollisionWorld) {
    for (let z = -WORLD_HALF; z < WORLD_HALF; z += ROOT)
      for (let x = -WORLD_HALF; x < WORLD_HALF; x += ROOT) this.roots.push(this.make(x, z, ROOT));
    const n = Math.max(2, Math.min(4, (navigator.hardwareConcurrency || 4) - 2));
    for (let i = 0; i < n; i++) {
      const w = new Worker(new URL('./chunk.worker.ts', import.meta.url), { type: 'module' });
      w.onmessage = (e) => this.onMessage(i, e.data as ChunkResult | AtlasResult);
      w.onerror = (e) => console.error('chunk worker error', e.message);
      this.workers.push(w);
      this.load.push(0);
    }
    const req: AtlasRequest = { type: 'atlas', id: 0, res: 512, half: WORLD_HALF };
    this.workers[0].postMessage(req);
    this.load[0]++;
  }

  private make(x: number, z: number, size: number) {
    const n = new QNode(this.nextId++, x, z, size);
    this.nodes.set(n.id, n);
    return n;
  }

  private onMessage(wi: number, msg: ChunkResult | AtlasResult) {
    this.load[wi]--;
    if (msg.type === 'atlas') {
      this.atlas = { res: msg.res, half: msg.half, height: msg.height, biome: msg.biome };
      this.onAtlas?.(this.atlas);
      return;
    }
    const node = this.nodes.get(msg.id);
    if (!node || node.state !== 'loading') return;
    this.build(node, msg);
  }

  private build(node: QNode, d: ChunkResult) {
    const group = new THREE.Group();
    group.visible = false;
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(d.position, 3));
    g.setAttribute('normal', new THREE.BufferAttribute(d.normal, 3));
    g.setAttribute('color', new THREE.BufferAttribute(d.color, 3));
    g.setIndex(new THREE.BufferAttribute(d.index, 1));
    const cx = node.x + node.size / 2;
    const cz = node.z + node.size / 2;
    const cy = (d.minY + d.maxY) / 2;
    const rad = Math.hypot(node.size * 0.7072, (d.maxY - d.minY) / 2);
    g.boundingSphere = new THREE.Sphere(new THREE.Vector3(cx, cy, cz), rad);
    const terrain = new THREE.Mesh(g, this.terrainMat);
    terrain.receiveShadow = true;
    terrain.matrixAutoUpdate = false;
    group.add(terrain);
    if (d.flora) {
      const fg = new THREE.BufferGeometry();
      fg.setAttribute('position', new THREE.BufferAttribute(d.flora.position, 3));
      fg.setAttribute('normal', new THREE.BufferAttribute(d.flora.normal, 3));
      fg.setAttribute('color', new THREE.BufferAttribute(d.flora.color, 3));
      fg.setAttribute('sway', new THREE.BufferAttribute(d.flora.sway, 2));
      fg.boundingSphere = new THREE.Sphere(new THREE.Vector3(cx, cy + 10, cz), rad + 24);
      const flora = new THREE.Mesh(fg, this.floraMat);
      flora.castShadow = node.size <= 128;
      flora.receiveShadow = true;
      flora.matrixAutoUpdate = false;
      group.add(flora);
      node.flora = flora;
    }
    if (d.grass) {
      const grass = makeGrassMesh(d.grass, new THREE.Sphere(new THREE.Vector3(cx, cy, cz), rad + 3));
      grass.matrixAutoUpdate = false;
      group.add(grass);
      node.grass = grass;
    }
    if (d.props) {
      const props: Prop[] = [];
      for (let i = 0; i < d.props.length; i += 6) {
        const p: Prop = { kind: d.props[i], x: d.props[i + 1], y: d.props[i + 2], z: d.props[i + 3], r: d.props[i + 4], h: d.props[i + 5] };
        props.push(p);
        if (p.r > 0) this.collision.addCircle(node.id, p.x, p.z, p.r, p.y - 1, p.y + p.h, 0, p);
      }
      node.props = props;
    }
    node.group = group;
    node.state = 'ready';
    this.group.add(group);
  }

  private dispose(node: QNode) {
    if (node.group) {
      this.group.remove(node.group);
      node.group.traverse((o) => {
        const m = o as THREE.Mesh;
        if (m.geometry) m.geometry.dispose();
      });
    }
    if (node.props) this.collision.removeOwner(node.id);
    node.group = null;
    node.grass = null;
    node.flora = null;
    node.props = null;
    node.state = 'empty';
    node.shown = false;
  }

  private want(node: QNode) {
    if (node.state === 'empty') {
      node.state = 'loading';
      this.queue.push(node);
    }
  }

  private setShown(node: QNode, v: boolean) {
    if (node.shown === v) return;
    node.shown = v;
    if (node.group) node.group.visible = v;
  }
  private hideTree(node: QNode) {
    this.setShown(node, false);
    if (node.children) for (const c of node.children) this.hideTree(c);
  }

  private visit(node: QNode) {
    node.lastUsed = this.frame;
    const d = node.dist(this.cam.x, this.cam.z);
    // hysteresis keeps nodes from flickering at the split boundary
    const k = node.split ? SPLIT_K * 1.15 : SPLIT_K;
    const wantSplit = node.size > MIN && d < node.size * k;
    this.want(node);
    if (wantSplit) {
      if (!node.children) {
        const h = node.size / 2;
        node.children = [this.make(node.x, node.z, h), this.make(node.x + h, node.z, h), this.make(node.x, node.z + h, h), this.make(node.x + h, node.z + h, h)];
      }
      let ready = true;
      for (const c of node.children) {
        c.lastUsed = this.frame;
        this.want(c);
        if (c.state !== 'ready') ready = false;
      }
      if (ready) {
        node.split = true;
        this.setShown(node, false);
        for (const c of node.children) this.visit(c);
        return;
      }
    }
    node.split = false;
    if (node.children) for (const c of node.children) this.hideTree(c);
    if (node.state === 'ready') {
      this.setShown(node, true);
      this.stats.shown++;
      if (node.size === MIN) this.leaves64.push(node);
    }
  }

  update(camPos: THREE.Vector3) {
    this.frame++;
    this.cam.copy(camPos);
    this.stats.shown = 0;
    this.leaves64.length = 0;
    for (const r of this.roots) this.visit(r);

    // grass density falls with distance: draw only a leading slice of each node's shuffled tufts
    for (const n of this.leaves64) {
      if (!n.grass) continue;
      const d = n.dist(camPos.x, camPos.z);
      const f = 1 - smoothstep(26, 92, d);
      const g = n.grass.geometry as THREE.InstancedBufferGeometry;
      g.instanceCount = Math.floor((n.grass.userData.total as number) * f);
      n.grass.visible = g.instanceCount > 0;
      if (n.flora) n.flora.castShadow = d < 150;
    }

    // dispatch, nearest first
    if (this.queue.length) {
      this.queue.sort((a, b) => a.dist(camPos.x, camPos.z) - a.size * 0.25 - (b.dist(camPos.x, camPos.z) - b.size * 0.25));
      for (let wi = 0; wi < this.workers.length && this.queue.length; wi++) {
        while (this.load[wi] < 2 && this.queue.length) {
          const n = this.queue.shift()!;
          if (n.state !== 'loading') continue;
          // drop stale requests the camera has left behind
          if (this.frame - n.lastUsed > 30) {
            n.state = 'empty';
            continue;
          }
          const req: ChunkRequest = { type: 'chunk', id: n.id, x: n.x, z: n.z, size: n.size };
          this.workers[wi].postMessage(req);
          this.load[wi]++;
        }
      }
    }

    // free what has not been wanted for a while
    if (this.frame % 90 === 0) {
      for (const n of this.nodes.values()) {
        if (n.state === 'ready' && !n.shown && this.frame - n.lastUsed > 600) this.dispose(n);
      }
      this.prune(this.roots);
    }
    this.stats.loading = this.queue.length + this.load.reduce((a, b) => a + b, 0);
    this.stats.nodes = this.nodes.size;
  }

  /** Drop long-unused subtrees so the node map does not grow without bound. */
  private prune(list: QNode[]) {
    for (const n of list) {
      if (!n.children) continue;
      const stale = n.children.every((c) => !c.children && c.state === 'empty' && this.frame - c.lastUsed > 900);
      if (stale && !n.split) {
        for (const c of n.children) this.nodes.delete(c.id);
        n.children = null;
      } else this.prune(n.children);
    }
  }

  /** True once nothing near the camera is still generating. */
  settled(): boolean {
    return this.stats.loading === 0 && this.stats.shown > 0;
  }

  /** Visit generated props (trees, rocks, berry bushes) near a point. */
  nearProps(x: number, z: number, radius: number, fn: (p: Prop, nodeId: number) => void) {
    for (const n of this.leaves64) {
      if (!n.props || n.dist(x, z) > radius) continue;
      for (const p of n.props) {
        const dx = p.x - x;
        const dz = p.z - z;
        if (dx * dx + dz * dz < radius * radius) fn(p, n.id);
      }
    }
  }
}

export { Flora };
export type { Prop };
